import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Open Cube OS","description":"","frontmatter":{},"headers":[],"relativePath":"root/README.md","filePath":"root/README.md"}'),i={name:"root/README.md"};function o(n,e,l,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[r(`<div align="center"><h1 id="open-cube-os" tabindex="-1">Open Cube OS <a class="header-anchor" href="#open-cube-os" aria-label="Permalink to &quot;Open Cube OS&quot;">​</a></h1><p><strong>A from-scratch x86_64 kernel with a WinRE-style recovery shell.</strong></p><p>Current release: <strong>v2.1.0</strong> - the 17-issue fix release on top of the 2.0.0 ring-3 re-architecture: CI green again (and now a hard release gate), the docs/interface truth per-entry (v1 233-command mapping complete, the 278-declaration interface comparison, the declared deletion register), regenerated command reference, website data integrity (see <a href="https://github.com/cubestudio-dev/OpenCubeOS/releases" target="_blank" rel="noreferrer">Releases</a>).</p><p><code>oc&gt;</code> is the prompt. Everything is extensible.</p><p><a href="https://cubestudio-dev.github.io/OpenCubeOS/" target="_blank" rel="noreferrer">Website</a> · <a href="https://cubestudio-dev.github.io/OpenCubeOS/docs/" target="_blank" rel="noreferrer">Documentation</a> · <a href="#downloads">Downloads</a> · <a href="./BUILDING.html">Building</a> · <a href="./ARCHITECTURE.html">Architecture</a> · <a href="./INTERFACES.html">Interface Reference</a></p></div><hr><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>Open Cube OS is <strong>L0 + L1</strong>: a complete, self-contained 64-bit kernel that boots on real hardware and in QEMU, launches its default ring-3 application (the ush user shell, <strong>251 commands</strong> across the L0 recovery shell and the L1 service surface), and falls back to the recovery-shell prompt (<code>oc&gt;</code>) when the ring-3 world cannot start.</p><ul><li><strong>Not a Linux fork.</strong> 130,526 lines of original C/assembly under Apache 2.0 (verify: see <em>Stats</em> below).</li><li><strong>Boots everywhere the PC platform goes:</strong> hybrid BIOS + UEFI ISO, 512 MiB RAM is comfortable, disk optional.</li><li><strong>A real kernel:</strong> preemptive scheduler, 4-level paging, ring-3 user programs with 54 syscalls, VFS over FAT32/exFAT/ext4/ramfs, a full TCP/IP stack with TLS 1.2/1.3 and SSH (client <em>and</em> server), 16 driver families from NVMe to xHCI to ACPI AML, crash dumps, hardware watchdog (Intel TCO / ACPI WDAT), OTA A/B updates.</li><li><strong>A recovery shell by design:</strong> the system <em>is</em> the WinRE-style environment - boot, diagnose, repair, install, update.</li></ul><p>The two-layer architecture:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L0  Open Cube OS        kernel + oc&gt; recovery shell     &lt;- this repo</span></span>
<span class="line"><span>L1  ring-3 services     17 SYS_L1SVC categories / 158 ops + ush</span></span></code></pre></div><p>2.0.0 ships the L1 side in-tree: <code>l1apps/</code> holds the ring-3 applications (ush - the default boot entry - plus ld.so and the dynamic-linking test programs), and every operational command class moved behind the SYS_L1SVC service surface (<a href="./INTERFACES.html">INTERFACES.md</a> - the v1-&gt;v2 mapping table is the compatibility contract).</p><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>What you get</th></tr></thead><tbody><tr><td>Boot</td><td>GRUB 2.12 hybrid ISO (BIOS El Torito + UEFI image), multiboot2 with the kernel attached as a <code>self</code> module, A/B slot menu</td></tr><tr><td>Memory</td><td>PMM bitmap over the multiboot2 map, 4-level VMM, kmalloc heap with real growth via #PF</td></tr><tr><td>CPU</td><td>Preemptive priority + round-robin scheduler, 256-gate IDT with IST stacks, 100 Hz PIT + HPET/PM-timer/TSC sources, LAPIC</td></tr><tr><td>Ring 3</td><td>ELF loader, 54 syscalls, signals, fork/exec/pipes/select/mmap, dynamic linking (in-tree ld.so, PIE, dlsym); SYS_L1SVC + SYS_NETCMD service bridges</td></tr><tr><td>Storage</td><td>AHCI, ATA/ATA-DMA, NVMe, virtio-blk, USB MSC, SCSI (LSI); FAT32 with LFN, exFAT, ext4, ramfs; GPT/MBR partitions; A/B slots</td></tr><tr><td>Network</td><td>e1000/e1000e/igb/ixgbe/rtl8139/rtl8169-family/BCM57xx drivers, ARP/IPv4/ICMP/UDP/DNS/TCP with congestion control, sockets, firewall, HTTPS client (TLS 1.2/1.3 + X.509 chains), SSH client + sshd</td></tr><tr><td>USB</td><td>UHCI, OHCI, EHCI, xHCI; mass storage, HID, serial, audio classes</td></tr><tr><td>Media</td><td>HDA / AC97 / SB16 / ES1370 / virtio sound; UVC cameras with MJPEG</td></tr><tr><td>Platform</td><td>ACPI (FADT/DSDT/MCFG, real AML walker, S3 suspend/resume), Intel TCO + ACPI WDAT hardware watchdogs, HPET, i2c/SMBus</td></tr><tr><td>Shell</td><td>ush (ring 3, default boot entry): 133 service commands + built-ins with pipes/redirection/wildcards/env/aliases/jobs; oc&gt; recovery shell: 99 commands</td></tr><tr><td>TUI</td><td>Desktop, taskbar, menus, forms, editor, system apps - plus a Chinese console layer (16x16 font, pinyin IME)</td></tr><tr><td>Reliability</td><td>Crash dumps to serial + /etc crashlog, kernel log with rotation + levels + filters, health monitor (CPU/mem/tasks/IO + JSON export), OTA with SHA256 + signatures and rollback</td></tr></tbody></table><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># build (Linux): needs gcc nasm xorriso mtools grub-common</span></span>
<span class="line"><span>#               grub-pc-bin grub-efi-amd64-bin zip python3</span></span>
<span class="line"><span>./build.sh iso</span></span>
<span class="line"><span></span></span>
<span class="line"><span># run it</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512 -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># inside the guest (the default boot entry is the ring-3 ush shell)</span></span>
<span class="line"><span>ush&gt; help</span></span>
<span class="line"><span>ush&gt; dhcp</span></span>
<span class="line"><span>ush&gt; ping 10.0.2.2</span></span>
<span class="line"><span>ush&gt; wget 10.0.2.2</span></span>
<span class="line"><span>ush&gt; uname -a</span></span>
<span class="line"><span>ush&gt; exit          # -&gt; drops into the oc&gt; recovery shell (99 commands)</span></span></code></pre></div><p>UEFI instead of BIOS: <code>make run-uefi</code>. Windows hosts: <code>build.ps1</code> (WSL2/MSYS2). Full guides: <a href="./BUILDING.html">BUILDING.md</a>.</p><h2 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h2><p>Every release ships three assets from the same byte-reproducible pipeline - the current release is always on the <a href="https://github.com/cubestudio-dev/OpenCubeOS/releases" target="_blank" rel="noreferrer">GitHub releases page</a> and mirrored on the <a href="https://cubestudio-dev.github.io/OpenCubeOS/" target="_blank" rel="noreferrer">website downloads page</a>:</p><table tabindex="0"><thead><tr><th>Asset</th><th>What it is</th></tr></thead><tbody><tr><td><code>opencube-2.1.0.iso</code></td><td>Hybrid BIOS+UEFI bootable ISO - boot it in QEMU or write to USB</td></tr><tr><td><code>opencube-2.1.0-src.zip</code></td><td>Deterministic source zip (<code>git archive</code>)</td></tr><tr><td><code>opencube-2.1.0-update.tar.gz</code></td><td>OTA update package (SHA256 + signature verified, A/B slots)</td></tr></tbody></table><p>Each release note carries the SHA256 of all three; the website, the Release and the private mirror hold byte-identical copies.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><ul><li><a href="./BUILDING.html">BUILDING.md</a> - build on Linux/Windows, QEMU, cross-compilation (ARM64/RISC-V shells), reproducible verification</li><li><a href="./ARCHITECTURE.html">ARCHITECTURE.md</a> - the L0 architecture, top to bottom</li><li><a href="./INTERFACES.html">INTERFACES.md</a> - the 251-command surface by home, the v1-&gt;v2 mapping and the L1SVC service tables (generated from the tree: <code>make api-docs</code>)</li><li><a href="./FAQ.html">FAQ.md</a> - common questions</li><li><a href="./CONTRIBUTING.html">CONTRIBUTING.md</a> - ground rules and the PR bar</li><li>The full documentation center (user manual, developer handbook, driver bring-up guides, L1 extension guide, internals): <strong><a href="https://cubestudio-dev.github.io/OpenCubeOS/docs/" target="_blank" rel="noreferrer">https://cubestudio-dev.github.io/OpenCubeOS/docs/</a></strong></li></ul><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><p>All numbers below are machine-verified at build time (<code>make api-docs</code> writes <code>docs/data/*.json</code>; the README verification command is quoted per item):</p><ul><li><strong>Source code</strong>: 130,526 lines across 379 files - core + arch + drivers + services + recovery + tui + chinese + boot + l1apps, headers included, docs/tools/tests and generated data blobs excluded. Verify: <code>git ls-files | grep -E &#39;\\.(c|h|S)$&#39; | grep -E &#39;^(core|arch|drivers|services|recovery|tui|chinese|boot|l1apps)/&#39; | grep -v &#39;^core/generated/&#39; | grep -vE &#39;userprogs_data|chinese_font_data|pinyin_data|grub_boot_data&#39; | xargs wc -l</code></li><li><strong>Commands</strong>: 251 total - 99 in the L0 recovery shell (<code>help -a</code> at the <code>oc&gt;</code> prompt) + 133 ring-3 SYS_L1SVC service commands + 19 ush built-ins. Every 1.0.0 command is mapped - see the v1-&gt;v2 table in <a href="./INTERFACES.html">INTERFACES.md</a>.</li><li><strong>L1SVC service surface</strong>: 17 categories / 158 numbered ops - see <a href="./INTERFACES.html">INTERFACES.md</a> for the exact tables.</li><li><strong>Syscalls</strong>: 54 - verify: <code>grep -c &#39;#define SYS_&#39; core/core_syscall.h</code></li><li><strong>CI</strong>: green on every push - build, ISO, packages, host tests and the reproducibility gate (<code>.github/workflows/build.yml</code>).</li></ul><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>Apache 2.0 - see <a href="./LICENSE.html">LICENSE</a>. Every source file carries <code>SPDX-License-Identifier: Apache-2.0</code>.</p><p>Copyright 2026 cubestudio-dev &lt;cubestudio@qq.com&gt;</p>`,25)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
